              economyPressure: containsAny('aether', 'energy', 'nộ', 'rage', 'resource', 'cost') ? 1 : 0,
              scalingCeiling: containsAny('stack', 'vĩnh viễn', 'evolve', 'tiến hóa', 'growth') ? 2 : 0,
