      for (const cellOneBased of thanhMaoSonCluster)
          occupiedModuleCells.add(cellOneBased);
      const forgeShopState = { ownerAvatarId: null, closesAtTurnAvatarId: null, closedManually: false, offers: [] };
      const fortuneTargets = [];
